def f(g):
    H,W=len(g),len(g[0])
    o=[r[:] for r in g]
    from collections import deque
    for cval in set(x for r in g for x in r):
        if cval==9 or cval==6 and True: pass
    # find max color used
    colors=set(x for r in g for x in r)
    for cval in colors:
        seen=[[False]*W for _ in range(H)]
        for cy in range(H):
            for cx in range(W):
                if g[cy][cx]==cval and not seen[cy][cx]:
                    q=deque([(cy,cx)]); seen[cy][cx]=True; comp=[]
                    while q:
                        y,x=q.popleft(); comp.append((y,x))
                        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==cval:
                                seen[ny][nx]=True; q.append((ny,nx))
        rs=[y for y,_ in comp]; cs=[x for _,x in comp]
        r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
        # check border: all cells on border cycle equal cval
        border=True
        for x in range(c0,c1+1):
            if g[r0][x]!=cval or g[r1][x]!=cval: border=False
        for y in range(r0,r1+1):
            if g[y][c0]!=cval or g[y][c1]!=cval: border=False
        if border and r1>r0 and c1>c0:
            for y in range(r0+1,r1):
                for x in range(c0+1,c1):
                    if g[y][x]!=cval: o[y][x]=4
    return o
