def f(g):
    H,W=len(g),len(g[0])
    o=[r[:] for r in g]
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    # precompute nearest non-bg in each direction for every cell
    def ndirs(i,j,axis):
        if axis=='U':
            for k in range(i-1,-1,-1):
                if g[k][j]!=bg: return g[k][j]
            return None
        if axis=='D':
            for k in range(i+1,H):
                if g[k][j]!=bg: return g[k][j]
            return None
        if axis=='L':
            for k in range(j-1,-1,-1):
                if g[i][k]!=bg: return g[i][k]
            return None
        if axis=='R':
            for k in range(j+1,W):
                if g[i][k]!=bg: return g[i][k]
            return None
    for i in range(H):
        for j in range(W):
            if g[i][j]==bg: continue
            u=d=ll=r=None
            u=ndirs(i,j,'U'); d=ndirs(i,j,'D'); ll=ndirs(i,j,'L'); r=ndirs(i,j,'R')
            if (u is not None and d is not None and ll is not None and r is not None):
                o[i][j]=4
    return o

